create or replace function kg_private.validate_research_case(p_project uuid,p_paper uuid,p jsonb) returns void language plpgsql set search_path='' as $$
declare x jsonb;c jsonb;ids text[];lo numeric;hi numeric;
begin
 if octet_length(p::text)>131072 or not kg_private.case_json_shape(p,$schema${"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"compounds":{"minItems":2,"maxItems":8,"type":"array","items":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"name":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},"aliases":{"maxItems":8,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"node_type":{"type":"string","enum":["discrete_molecule","intermediate","polymer","polymer_site","mixture","class"]},"structure_context":{"type":"string","enum":["free","bound","polymer_site","unknown"]},"stereochemistry":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"protonation":{"anyOf":[{"type":"string","maxLength":500},{"type":"null"}]},"formula":{"anyOf":[{"type":"string","maxLength":200},{"type":"null"}]},"charge":{"anyOf":[{"type":"integer","minimum":-100,"maximum":100},{"type":"null"}]},"epistemic_status":{"type":"string","enum":["observed","hypothetical","unspecified"]},"structure":{"type":"object","properties":{"schema_version":{"type":"string","const":"chemical-structure/0.1"},"smiles":{"anyOf":[{"type":"string","minLength":1,"maxLength":4096},{"type":"null"}]},"inchi":{"anyOf":[{"type":"string","maxLength":4096,"pattern":"^InChI=1S?\\/[^\\s<>]+$"},{"type":"null"}]},"cas":{"type":["string","null"]},"representation":{"type":"string","enum":["ground_state","transition_state","unknown"]},"source_anchor_id":{"anyOf":[{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},{"type":"null"}]},"attribution":{"type":"string","enum":["authors","analyst","not_reported"]}},"required":["schema_version","smiles","inchi","cas","representation","source_anchor_id","attribution"],"additionalProperties":false}},"required":["id","name","aliases","node_type","structure_context","stereochemistry","protonation","formula","charge","epistemic_status"],"additionalProperties":false}},"reaction":{"type":"object","properties":{"description":{"type":"object","properties":{"schema_version":{"type":"string","const":"reaction-description/0.1"},"reaction_type":{"anyOf":[{"type":"string","minLength":1,"maxLength":200},{"type":"null"}]},"reversibility":{"type":"string","enum":["reversible","irreversible","unknown"]},"description":{"anyOf":[{"type":"string","minLength":1,"maxLength":8000},{"type":"null"}]},"source_anchor_id":{"anyOf":[{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},{"type":"null"}]},"attribution":{"type":"string","enum":["authors","analyst","not_reported"]}},"required":["schema_version","reaction_type","reversibility","description","source_anchor_id","attribution"],"additionalProperties":false},"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"representation_scope":{"type":"string","enum":["net_conversion","elementary_step","pathway_segment"]},"equation_balance_status":{"type":"string","enum":["checked","unchecked","not_applicable","unknown"]},"product_inventory_status":{"type":"string","enum":["complete","partial","unknown"]},"participants":{"minItems":2,"maxItems":16,"type":"array","items":{"type":"object","properties":{"compound_id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"role":{"type":"string","enum":["reactant","product","formal_auxiliary"]},"coefficient":{"anyOf":[{"type":"number","exclusiveMinimum":0,"maximum":1000000},{"type":"null"}]},"primary_for_display":{"type":"boolean"}},"required":["compound_id","role","coefficient","primary_for_display"],"additionalProperties":false}}},"required":["id","representation_scope","equation_balance_status","product_inventory_status","participants"],"additionalProperties":false},"claim":{"type":"object","properties":{"scope":{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},"proposition":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"asserted_by":{"type":"string","enum":["authors","analyst"]}},"required":["scope","proposition","asserted_by"],"additionalProperties":false},"experiment":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"original_experiment_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"independence_group_id":{"anyOf":[{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"},{"type":"null"}]},"origin_resolution_status":{"type":"string","enum":["confirmed","unresolved"]},"stage":{"type":"string","enum":["reaction","pretreatment","workup","analysis"]},"conditions":{"maxItems":20,"type":"array","items":{"type":"object","properties":{"key":{"type":"string","minLength":1},"dimension":{"type":"string","minLength":1},"basis":{"type":"string","minLength":1},"unit":{"type":"string"},"value_state":{"type":"string","enum":["reported","not_reported","unknown","not_applicable","ambiguous"]},"kind":{"type":"string","enum":["interval","controlled_term","composition"]},"lower":{"type":["number","null"]},"upper":{"type":["number","null"]},"lower_inclusive":{"type":"boolean"},"upper_inclusive":{"type":"boolean"},"terms":{"type":"array","items":{"type":"string"}},"inventory_complete":{"type":"boolean"},"raw_value_text":{"type":"string"},"raw_unit":{"type":"string"},"derivation":{"type":"string","enum":["reported","calculated"]},"calculation":{"type":["string","null"]}},"required":["key","dimension","basis","unit","value_state","kind","lower","upper","lower_inclusive","upper_inclusive","terms","inventory_complete","raw_value_text","raw_unit","derivation","calculation"],"additionalProperties":false}}},"required":["id","original_experiment_id","independence_group_id","origin_resolution_status","stage","conditions"],"additionalProperties":false},"evidence":{"type":"object","properties":{"id":{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},"stance":{"type":"string","enum":["supports","refutes","inconclusive"]},"evidence_type":{"type":"string","enum":["directly_observed","strongly_supported","proposed","adopted_from_prior_literature","speculative"]},"measured_scope":{"anyOf":[{"type":"string","enum":["product_presence","net_conversion","intermediate_presence","elementary_mechanism","pathway","order_of_steps"]},{"type":"null"}]},"epistemic_origin":{"type":"string","enum":["experiment_report","authors_interpretation","cited_interpretation","analyst_inference"]},"source_access":{"type":"string","enum":["fulltext","abstract_only","secondary_only","unavailable"]},"strength_rationale":{"type":"string","minLength":1,"maxLength":4000,"pattern":"\\S"},"alternatives_tested":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"limitations":{"maxItems":20,"type":"array","items":{"type":"string","minLength":1,"maxLength":200,"pattern":"\\S"}},"source_anchor_id":{"anyOf":[{"type":"string","format":"uuid","pattern":"^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$"},{"type":"null"}]}},"required":["id","stance","evidence_type","measured_scope","epistemic_origin","source_access","strength_rationale","alternatives_tested","limitations","source_anchor_id"],"additionalProperties":false}},"required":["compounds","reaction","claim","experiment","evidence"],"additionalProperties":false}$schema$::jsonb) then raise exception 'KG_INVALID';end if;
 select array_agg(id) into ids from (select value->>'id' id from jsonb_array_elements(p->'compounds') union all select p#>>'{reaction,id}' union all select p#>>'{experiment,id}' union all select p#>>'{evidence,id}') q;
 if cardinality(ids)<>(select count(distinct id) from unnest(ids) id) then raise exception 'KG_INVALID';end if;
 if not exists(select from jsonb_array_elements(p#>'{reaction,participants}') part where part.value->>'role'='reactant') or not exists(select from jsonb_array_elements(p#>'{reaction,participants}') part where part.value->>'role'='product') then raise exception 'KG_INVALID';end if;
 for x in select value from jsonb_array_elements(p#>'{reaction,participants}') loop if not exists(select from jsonb_array_elements(p->'compounds') comp where comp.value->>'id'=x->>'compound_id') then raise exception 'KG_INVALID';end if;end loop;
 if p#>>'{claim,scope}'='elementary_mechanism' and p#>>'{reaction,representation_scope}'<>'elementary_step' then raise exception 'KG_SCOPE';end if;
 if p#>>'{evidence,evidence_type}'='directly_observed' and p#>>'{evidence,measured_scope}' is distinct from p#>>'{claim,scope}' then raise exception 'KG_SCOPE';end if;
 if p#>>'{evidence,evidence_type}'='strongly_supported' and (jsonb_array_length(p#>'{evidence,alternatives_tested}')=0 or jsonb_array_length(p#>'{evidence,limitations}')=0) then raise exception 'KG_INVALID';end if;
 if p#>>'{experiment,origin_resolution_status}'='confirmed' and (p#>>'{experiment,original_experiment_id}' is null or p#>>'{experiment,independence_group_id}' is null or p#>>'{evidence,evidence_type}'='adopted_from_prior_literature') then raise exception 'KG_ORIGIN';end if;
 for c in select value from jsonb_array_elements(p#>'{experiment,conditions}') loop
  lo:=(c->>'lower')::numeric;hi:=(c->>'upper')::numeric;
  if c->>'value_state'<>'reported' then if lo is not null or hi is not null or jsonb_array_length(c->'terms')<>0 then raise exception 'KG_CONDITIONS';end if;
  elsif c->>'kind'='interval' then
   if jsonb_array_length(c->'terms')<>0 or lo is null and hi is null or lo>hi or lo=hi and (not (c->>'lower_inclusive')::boolean or not (c->>'upper_inclusive')::boolean) then raise exception 'KG_CONDITIONS';end if;
  elsif lo is not null or hi is not null or jsonb_array_length(c->'terms')=0 then raise exception 'KG_CONDITIONS';end if;
  if c->>'value_state'='reported' and c->>'derivation'='calculated' and coalesce(btrim(c->>'calculation'),'')='' then raise exception 'KG_CONDITIONS';end if;
 end loop;
 if p#>>'{evidence,source_anchor_id}' is not null and not exists(select from public.source_anchors a join public.paper_documents d on d.project_id=a.project_id and d.id=a.paper_document_id where a.project_id=p_project and a.id=(p#>>'{evidence,source_anchor_id}')::uuid and d.paper_id=p_paper) then raise exception 'KG_SOURCE';end if;
 for x in select value->'structure' from jsonb_array_elements(p->'compounds') where value ? 'structure' union all select p#>'{reaction,description}' where p#>'{reaction,description}' is not null loop
 if x->>'source_anchor_id' is not null and not exists(select from public.source_anchors a join public.paper_documents d on d.project_id=a.project_id and d.id=a.paper_document_id where a.project_id=p_project and a.id=(x->>'source_anchor_id')::uuid and d.paper_id=p_paper) then raise exception 'KG_SOURCE';end if;
 if x->>'cas' is not null then
 if x->>'cas' !~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$' then raise exception 'KG_INVALID';end if;
 if (select sum(substring(reverse(replace(x->>'cas','-','')) from i for 1)::integer*(i-1))%10 from generate_series(2,length(replace(x->>'cas','-','')))i)<>right(x->>'cas',1)::integer then raise exception 'KG_INVALID';end if;
 end if;
 end loop;
end$$;

grant kg_research_writer to current_user with set true;
grant create on schema public to kg_research_writer;
set local role kg_research_writer;
